import React, { useState, useEffect } from 'react';
import { 
  Container, Row, Col, Card, Form, 
  Alert, Table, Badge, Spinner, Button 
} from 'react-bootstrap';
import { useSearchParams, useNavigate } from 'react-router-dom';
import { useNotification } from '../contexts/NotificationContext';
import { useSearch } from '../contexts/SearchContext';

const PackageSearchPage = () => {
  const [searchParams] = useSearchParams();
  const navigate = useNavigate();
  const { showNotification } = useNotification();
  const { addToHistory } = useSearch();
  
  const [keyword, setKeyword] = useState(searchParams.get('q') || '');
  const [tahun, setTahun] = useState('2026');
  const [loading, setLoading] = useState(false);
  const [results, setResults] = useState([]);
  const [stats, setStats] = useState({ total: 0, totalValue: 0 });

  // Handle search from URL
  useEffect(() => {
    const query = searchParams.get('q');
    if (query) {
      setKeyword(query);
      handleSearch(query);
    }
  }, [searchParams]);

  const handleSearch = async (customKeyword = null) => {
    const searchKeyword = customKeyword || keyword;
    
    if (!searchKeyword.trim()) {
      showNotification('Masukkan kata kunci terlebih dahulu', 'warning');
      return;
    }

    setLoading(true);
    
    // Add to search history
    addToHistory({
      type: 'package',
      query: searchKeyword,
      timestamp: new Date().toISOString()
    });

    try {
      // Call backend API
      const response = await fetch(
        `http://localhost:5000/api/search/paket?keyword=${encodeURIComponent(searchKeyword)}&tahun=${tahun}`
      );
      
      const data = await response.json();
      
      if (data.status === 'success') {
        setResults(data.data);
        calculateStats(data.data);
        showNotification(`Ditemukan ${data.total} paket tender`, 'success');
      } else {
        showNotification(data.message, 'error');
        setResults([]);
      }
    } catch (error) {
      console.error('Search error:', error);
      showNotification('Gagal menghubungi backend', 'error');
      
      // Fallback demo data
      setResults(generateDemoData(searchKeyword));
      showNotification('Menampilkan data demo', 'info');
    } finally {
      setLoading(false);
    }
  };

  const calculateStats = (data) => {
    const total = data.length;
    let totalValue = 0;
    
    // Parse nilai pagu dari string seperti "Rp 1.5 M" atau "Rp 500 Juta"
    data.forEach(item => {
      const pagu = item.nilai_pagu || item.pagu || '';
      if (pagu.includes('M')) {
        const value = parseFloat(pagu.replace(/[^\d.]/g, '')) * 1000000000;
        totalValue += value;
      } else if (pagu.includes('Juta')) {
        const value = parseFloat(pagu.replace(/[^\d.]/g, '')) * 1000000;
        totalValue += value;
      } else if (pagu.includes('T')) {
        const value = parseFloat(pagu.replace(/[^\d.]/g, '')) * 1000000000000;
        totalValue += value;
      }
    });
    
    setStats({ total, totalValue });
  };

  const generateDemoData = (searchKeyword) => {
    return [
      {
        no: 1,
        kode_tender: `PU-${tahun}-001`,
        nama_paket: `Pembangunan Jalan ${searchKeyword} Tahun ${tahun}`,
        nilai_pagu: 'Rp 2.5 T',
        tanggal: `15 Januari ${tahun}`,
        tahun: tahun,
        lpse: 'pu',
        lpse_nama: 'Kementerian PU',
        satuan_kerja: 'Ditjen Bina Marga',
        url_detail: `https://spse.inaproc.id/pu/lelang/PU-${tahun}-001/pengumumanlelang`,
        confidence: 'demo'
      },
      {
        no: 2,
        kode_tender: `PU-${tahun}-002`,
        nama_paket: `Pembangunan Gedung ${searchKeyword} Tahun ${tahun}`,
        nilai_pagu: 'Rp 350 M',
        tanggal: `10 Februari ${tahun}`,
        tahun: tahun,
        lpse: 'pu',
        lpse_nama: 'Kementerian PU',
        satuan_kerja: 'Ditjen Cipta Karya',
        url_detail: `https://spse.inaproc.id/pu/lelang/PU-${tahun}-002/pengumumanlelang`,
        confidence: 'demo'
      },
      {
        no: 3,
        kode_tender: `KEMENKEU-${tahun}-001`,
        nama_paket: `Pengadaan ${searchKeyword} Kantor Tahun ${tahun}`,
        nilai_pagu: 'Rp 150 M',
        tanggal: `20 Maret ${tahun}`,
        tahun: tahun,
        lpse: 'kemenkeu',
        lpse_nama: 'Kementerian Keuangan',
        satuan_kerja: 'Ditjen Perbendaharaan',
        url_detail: `https://spse.inaproc.id/kemenkeu/lelang/KEMENKEU-${tahun}-001/pengumumanlelang`,
        confidence: 'demo'
      }
    ];
  };

  const handleExport = async () => {
    try {
      const response = await fetch(
        `http://localhost:5000/api/export/csv?type=paket&keyword=${encodeURIComponent(keyword)}&tahun=${tahun}`,
        { method: 'GET' }
      );
      
      if (response.ok) {
        const blob = await response.blob();
        const url = window.URL.createObjectURL(blob);
        const a = document.createElement('a');
        a.href = url;
        a.download = `paket-${keyword}-${tahun}.csv`;
        document.body.appendChild(a);
        a.click();
        a.remove();
        showNotification('Data berhasil diexport', 'success');
      }
    } catch (error) {
      showNotification('Gagal mengexport data', 'error');
    }
  };

  const formatCurrency = (value) => {
    if (value >= 1000000000000) {
      return `Rp ${(value / 1000000000000).toFixed(2)} T`;
    } else if (value >= 1000000000) {
      return `Rp ${(value / 1000000000).toFixed(2)} M`;
    } else if (value >= 1000000) {
      return `Rp ${(value / 1000000).toFixed(2)} Juta`;
    }
    return `Rp ${value.toLocaleString()}`;
  };

  const handleClear = () => {
    setKeyword('');
    setResults([]);
    setStats({ total: 0, totalValue: 0 });
  };

  return (
    <Container className="py-4">
      <Row className="mb-4">
        <Col>
          <h1 className="display-6 fw-bold">
            <i className="fas fa-box me-2"></i>
            Pencarian Paket Tender
          </h1>
          <p className="text-muted">
            Cari data tender berdasarkan kata kunci
          </p>
        </Col>
      </Row>

      {/* Search Form */}
      <Row className="mb-4">
        <Col lg={8}>
          <Card className="shadow-sm">
            <Card.Body>
              <Form onSubmit={(e) => { e.preventDefault(); handleSearch(); }}>
                <Row>
                  <Col md={6}>
                    <Form.Group className="mb-3">
                      <Form.Label>
                        <i className="fas fa-search me-1"></i>
                        Kata Kunci
                      </Form.Label>
                      <Form.Control
                        type="text"
                        placeholder="Contoh: jalan, bangunan, pengadaan"
                        value={keyword}
                        onChange={(e) => setKeyword(e.target.value)}
                        disabled={loading}
                      />
                    </Form.Group>
                  </Col>
                  <Col md={4}>
                    <Form.Group className="mb-3">
                      <Form.Label>
                        <i className="fas fa-calendar me-1"></i>
                        Tahun
                      </Form.Label>
                      <Form.Select
                        value={tahun}
                        onChange={(e) => setTahun(e.target.value)}
                        disabled={loading}
                      >
                        <option value="2023">2023</option>
                        <option value="2024">2024</option>
                        <option value="2025">2025</option>
                        <option value="2026">2026</option>
                      </Form.Select>
                    </Form.Group>
                  </Col>
                  <Col md={2} className="d-flex align-items-end">
                    <button
                      type="submit"
                      className="btn btn-primary w-100"
                      disabled={loading || !keyword.trim()}
                    >
                      {loading ? (
                        <Spinner animation="border" size="sm" />
                      ) : (
                        <i className="fas fa-search"></i>
                      )}
                    </button>
                  </Col>
                </Row>
              </Form>
            </Card.Body>
          </Card>
        </Col>
        <Col lg={4}>
          <Card className="shadow-sm h-100">
            <Card.Body className="d-flex flex-column">
              <h6 className="card-title">
                <i className="fas fa-chart-bar me-1"></i>
                Statistik
              </h6>
              <div className="mt-auto">
                <div className="d-flex justify-content-between mb-2">
                  <span className="text-muted">Total Paket:</span>
                  <Badge bg="info">{stats.total}</Badge>
                </div>
                <div className="d-flex justify-content-between">
                  <span className="text-muted">Nilai Total:</span>
                  <Badge bg="success">{formatCurrency(stats.totalValue)}</Badge>
                </div>
              </div>
            </Card.Body>
          </Card>
        </Col>
      </Row>

      {/* Results */}
      {results.length > 0 && (
        <Row className="mb-4">
          <Col>
            <Card className="shadow-sm">
              <Card.Header className="bg-light d-flex justify-content-between align-items-center">
                <div>
                  <i className="fas fa-list me-2"></i>
                  Hasil Pencarian ({results.length} paket)
                </div>
                <div>
                  <Button
                    variant="success"
                    size="sm"
                    onClick={handleExport}
                    disabled={results.length === 0}
                  >
                    <i className="fas fa-download me-1"></i>
                    Export CSV
                  </Button>
                  <Button
                    variant="outline-danger"
                    size="sm"
                    className="ms-2"
                    onClick={handleClear}
                  >
                    <i className="fas fa-trash me-1"></i>
                    Clear
                  </Button>
                </div>
              </Card.Header>
              <Card.Body className="p-0">
                <Table responsive hover className="mb-0">
                  <thead className="table-light">
                    <tr>
                      <th>No</th>
                      <th>LPSE</th>
                      <th>Kode Tender</th>
                      <th>Nama Paket</th>
                      <th>Nilai Pagu</th>
                      <th>Tanggal</th>
                      <th>Satuan Kerja</th>
                      <th>Aksi</th>
                    </tr>
                  </thead>
                  <tbody>
                    {results.map((item, index) => (
                      <tr key={index}>
                        <td>{item.no || index + 1}</td>
                        <td>
                          <Badge bg={
                            item.lpse === 'pu' ? 'primary' :
                            item.lpse === 'kemenkeu' ? 'success' :
                            item.lpse === 'jabarprov' ? 'info' : 'secondary'
                          }>
                            {item.lpse_nama}
                          </Badge>
                        </td>
                        <td>
                          <code>{item.kode_tender}</code>
                        </td>
                        <td>
                          <strong>{item.nama_paket}</strong>
                        </td>
                        <td>
                          <Badge bg="warning">{item.nilai_pagu || item.pagu}</Badge>
                        </td>
                        <td>{item.tanggal}</td>
                        <td>
                          <small className="text-muted">{item.satuan_kerja}</small>
                        </td>
                        <td>
                          <button
                            className="btn btn-outline-primary btn-sm"
                            onClick={() => window.open(item.url_detail, '_blank')}
                            title="Lihat detail di SPSE"
                          >
                            <i className="fas fa-external-link-alt"></i>
                          </button>
                        </td>
                      </tr>
                    ))}
                  </tbody>
                </Table>
              </Card.Body>
              {results[0]?.confidence === 'demo' && (
                <Card.Footer className="bg-warning bg-opacity-10">
                  <div className="text-warning">
                    <i className="fas fa-exclamation-triangle me-2"></i>
                    Data demo - Gunakan untuk testing
                  </div>
                </Card.Footer>
              )}
            </Card>
          </Col>
        </Row>
      )}

      {/* Empty State */}
      {!loading && results.length === 0 && keyword && (
        <Row>
          <Col>
            <Alert variant="info" className="text-center">
              <i className="fas fa-info-circle fa-2x mb-3"></i>
              <h5>Tidak ada data ditemukan</h5>
              <p>Coba dengan kata kunci lain atau tahun yang berbeda</p>
            </Alert>
          </Col>
        </Row>
      )}

      {/* Popular Keywords */}
      <Row className="mt-4">
        <Col>
          <Card className="shadow-sm">
            <Card.Header className="bg-light">
              <i className="fas fa-fire me-2"></i>
              Kata Kunci Populer
            </Card.Header>
            <Card.Body>
              <div className="d-flex flex-wrap gap-2">
                {['jalan', 'bangunan', 'gedung', 'komputer', 'alat', 'konstruksi', 'jembatan', 'pengadaan'].map((word, index) => (
                  <Badge 
                    key={index}
                    bg="secondary"
                    className="p-2 hover-badge"
                    style={{ cursor: 'pointer' }}
                    onClick={() => {
                      setKeyword(word);
                      setTimeout(() => handleSearch(word), 100);
                    }}
                  >
                    {word}
                  </Badge>
                ))}
              </div>
            </Card.Body>
          </Card>
        </Col>
      </Row>

      {/* Tips */}
      <Row className="mt-4">
        <Col>
          <Card className="shadow-sm">
            <Card.Header className="bg-light">
              <i className="fas fa-lightbulb me-2"></i>
              Tips Pencarian Paket
            </Card.Header>
            <Card.Body>
              <Row>
                <Col md={4}>
                  <div className="d-flex mb-3">
                    <div className="flex-shrink-0">
                      <i className="fas fa-search text-primary"></i>
                    </div>
                    <div className="flex-grow-1 ms-3">
                      <h6>Kata Kunci Umum</h6>
                      <p className="small text-muted mb-0">
                        Gunakan kata kunci umum untuk hasil lebih banyak
                      </p>
                    </div>
                  </div>
                </Col>
                <Col md={4}>
                  <div className="d-flex mb-3">
                    <div className="flex-shrink-0">
                      <i className="fas fa-filter text-success"></i>
                    </div>
                    <div className="flex-grow-1 ms-3">
                      <h6>Filter Tahun</h6>
                      <p className="small text-muted mb-0">
                        Pilih tahun 2026 untuk data tender terbaru
                      </p>
                    </div>
                  </div>
                </Col>
                <Col md={4}>
                  <div className="d-flex mb-3">
                    <div className="flex-shrink-0">
                      <i className="fas fa-download text-warning"></i>
                    </div>
                    <div className="flex-grow-1 ms-3">
                      <h6>Multi-LPSE</h6>
                      <p className="small text-muted mb-0">
                        Pencarian dilakukan di semua LPSE yang tersedia
                      </p>
                    </div>
                  </div>
                </Col>
              </Row>
            </Card.Body>
          </Card>
        </Col>
      </Row>
    </Container>
  );
};

export default PackageSearchPage;